PRAGMA foreign_keys = ON;
CREATE TABLE song_masters (id TEXT PRIMARY KEY, album_id TEXT NOT NULL, artist_id TEXT NOT NULL, title TEXT NOT NULL);
CREATE TABLE storage_objects (id TEXT PRIMARY KEY, physical_key TEXT NOT NULL, suffix TEXT NOT NULL, content_type TEXT, size INTEGER NOT NULL, etag TEXT);
CREATE TABLE song_instances (id TEXT PRIMARY KEY, master_id TEXT NOT NULL REFERENCES song_masters(id) ON DELETE CASCADE, source_id TEXT NOT NULL, source_type TEXT, storage_uri TEXT NOT NULL, storage_object_id TEXT REFERENCES storage_objects(id), suffix TEXT NOT NULL, content_type TEXT, size INTEGER, missing INTEGER, tag_scanned INTEGER, parent_instance_id TEXT REFERENCES song_instances(id));
CREATE TABLE storage_entries (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, parent_id TEXT REFERENCES storage_entries(id) ON DELETE CASCADE, path TEXT NOT NULL, display_name TEXT NOT NULL, kind TEXT NOT NULL, object_id TEXT REFERENCES storage_objects(id), instance_id TEXT REFERENCES song_instances(id) ON DELETE SET NULL, companion_of TEXT REFERENCES storage_entries(id) ON DELETE SET NULL, CHECK ((kind = 'folder' AND object_id IS NULL) OR (kind = 'file' AND object_id IS NOT NULL)));
CREATE TABLE work_queue (id TEXT PRIMARY KEY, task_type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL);
CREATE TABLE transcode_jobs (id TEXT PRIMARY KEY, instance_id TEXT, output_instance_id TEXT);
CREATE TABLE playlist_songs (playlist_id TEXT, song_master_id TEXT);
CREATE TABLE annotations (user_id TEXT, item_id TEXT, item_type TEXT);
CREATE TABLE song_artists (song_id TEXT, artist_id TEXT);
